<script>
const STUDY_LEAVE_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/study-leave-profile";

export default {
  name: "StudyLeaveView",
  props: ["queries"],

  data() {
    return {
      loading: true,
      error: null,

      practitionerName: "",

      studyLeaveData: null,
      trainingCompletion: null,
      trainingPlanDetails: {},
      trainingRecommendationDetails: {},
      leaveRequests: [],

      outcomeValueSetItems: [],
    };
  },

  computed: {
    backLabel() {
      return (this.queries && this.queries.returnLabel) || "Back";
    },

    isDoctorException() {
      return (
        this.studyLeaveData !== null &&
        !this.trainingPlanDetails.id &&
        !this.trainingRecommendationDetails.id
      );
    },

    sectionMenu() {
      const sections = [
        {
          name: "overview",
          title: "Overview",
          desc: "Course, institution and academic details",
        },
      ];

      if (this.trainingPlanDetails.id) {
        sections.push({
          name: "training-plan",
          title: "Training Plan",
          desc: "Plan submitted by staff",
        });
      }

      if (this.trainingRecommendationDetails.id) {
        sections.push({
          name: "training-recommendation",
          title: "Recommendation",
          desc: "Training recommended by HR",
        });
      }

      if (this.trainingCompletion && this.trainingCompletion.outcome) {
        sections.push({
          name: "completion",
          title: "Completion",
          desc: "Training outcome and certificate",
        });
      }

      sections.push({
        name: "leave-requests",
        title: "Leave Requests",
        desc: `${this.leaveRequests.length} linked request(s)`,
      });

      return sections;
    },
  },

  async created() {
    if (!this.queries || !this.queries.id) {
      this.error = "No study leave record specified.";
      this.loading = false;
      return;
    }

    await Promise.all([this.loadOutcomeValueSet(), this.loadStudyLeave()]);
  },

  methods: {
    // ── Loading ───────────────────────────────────────────────────────
    async loadOutcomeValueSet() {
      try {
        const items = await this.$fhirutils.expand(
          "http://ihris.org/fhir/ValueSet/training-outcome-valueset",
        );
        this.outcomeValueSetItems = items || [];
      } catch (err) {
        console.error("loadOutcomeValueSet error:", err);
      }
    },

    async loadStudyLeave() {
      this.loading = true;
      this.error = null;

      try {
        const response = await fetch(`/fhir/Basic/${this.queries.id}`);
        if (!response.ok) {
          throw new Error("Study leave record not found");
        }

        const resource = await response.json();

        if (!resource.meta?.profile?.includes(STUDY_LEAVE_PROFILE)) {
          throw new Error("Resource is not a study leave record");
        }

        await this.extractStudyLeaveData(resource);
        await this.loadPractitioner();
        await this.loadTrainingPlanDetails();
        await this.loadTrainingRecommendationDetails();
        await this.loadLeaveRequests();
      } catch (err) {
        console.error("Error loading study leave:", err);
        this.error = err.message || "Failed to load study leave details";
      } finally {
        this.loading = false;
      }
    },

    // ── Extraction ───────────────────────────────────────────────────
    async resolveQualificationName(resource) {
      const qualNameOtherExt = resource.extension?.find((e) =>
        e.url.endsWith("/qualification-name-other"),
      );
      if (qualNameOtherExt?.valueString) return qualNameOtherExt.valueString;

      const qualNameExt = resource.extension?.find((e) =>
        e.url.endsWith("/qualification-name"),
      );
      if (qualNameExt?.valueReference?.display) {
        return qualNameExt.valueReference.display;
      }

      const ref = qualNameExt?.valueReference?.reference;
      if (!ref) return null;

      try {
        const id = ref.split("/")[1];
        const response = await fetch(`/fhir/Basic/${id}`);
        if (!response.ok) return null;

        const qualification = await response.json();
        return qualification.extension?.find((e) =>
          e.url.endsWith("/ihris-basic-name"),
        )?.valueString;
      } catch (error) {
        console.error("Error resolving qualification name:", error);
        return null;
      }
    },

    async extractStudyLeaveData(resource) {
      const getExt = (url, type) => {
        const ext = resource.extension?.find((e) => e.url.includes(url));
        return ext ? ext[type] : null;
      };

      this.studyLeaveData = {
        institution: getExt("planning-institution", "valueString"),
        course:
          getExt("planning-course", "valueString") ||
          (await this.resolveQualificationName(resource)),
        qualificationLevel: getExt("qualification-level", "valueCoding")
          ?.display,
        country: getExt("country", "valueCoding")?.display,
        trainingLocation: getExt("training-location", "valueString"),
        trainingType: getExt("training-type", "valueCoding")?.code,
        trainingTypeDisplay: getExt("training-type", "valueCoding")?.display,
        comments: getExt("comments", "valueString"),
      };

      // Practitioner reference
      const practRef = resource.extension?.find((e) =>
        e.url.includes("ihris-practitioner-reference"),
      )?.valueReference?.reference;
      this.practitionerRef = practRef;

      // Training plan / recommendation references
      this.trainingPlanRef = getExt(
        "training-plan-reference",
        "valueReference",
      )?.reference;
      this.trainingRecommendationRef = getExt(
        "training-recommendation-reference",
        "valueReference",
      )?.reference;

      // All linked leave requests (1..*)
      this.leaveRequestRefs =
        resource.extension
          ?.filter((e) => e.url.includes("leave-request-reference"))
          .map((e) => e.valueReference?.reference)
          .filter(Boolean) || [];

      // Training completion
      const completionExt = resource.extension?.find((e) =>
        e.url.includes("training-completion"),
      );
      if (completionExt) {
        const getCompletionExt = (url, type) => {
          const ext = completionExt.extension?.find((e) => e.url.includes(url));
          return ext ? ext[type] : null;
        };

        this.trainingCompletion = {
          outcome: getCompletionExt("training-outcome", "valueCoding")?.code,
          completionDate: getCompletionExt("completion-date", "valueDate"),
          certificateNumber: getCompletionExt(
            "certificate-number",
            "valueString",
          ),
        };
      }
    },

    async loadPractitioner() {
      if (!this.practitionerRef) return;

      try {
        const id = this.practitionerRef.split("/")[1];
        const response = await fetch(`/fhir/Practitioner/${id}?_elements=name`);
        const practitioner = await response.json();
        const name = practitioner.name?.[0];
        this.practitionerName = name
          ? `${name.given?.join(" ") || ""} ${name.family || ""}`.trim()
          : "Unknown";
      } catch (error) {
        console.error("Error loading practitioner:", error);
        this.practitionerName = "Unknown";
      }
    },

    async loadTrainingPlanDetails() {
      if (!this.trainingPlanRef) return;

      try {
        const planId = this.trainingPlanRef.split("/")[1];
        const response = await fetch(`/fhir/Basic/${planId}`);
        if (!response.ok) return;

        const plan = await response.json();
        const getExt = (url, type) => {
          const ext = plan.extension?.find((e) => e.url.includes(url));
          return ext ? ext[type] : null;
        };

        this.trainingPlanDetails = {
          id: planId,
          course:
            getExt("planning-course", "valueString") ||
            (await this.resolveQualificationName(plan)),
          institution: getExt("planning-institution", "valueString"),
          typeDisplay: getExt("training-type", "valueCoding")?.display,
          qualificationLevel: getExt("qualification-level", "valueCoding")
            ?.display,
          methodology: getExt("learning-methodology", "valueCoding")?.display,
          status: getExt("request-status", "valueCoding")?.code,
          statusDisplay: getExt("request-status", "valueCoding")?.display,
          startDate: getExt("start-date", "valueDate"),
          endDate: getExt("end-date", "valueDate"),
        };
      } catch (error) {
        console.error("Error loading training plan details:", error);
      }
    },

    async loadTrainingRecommendationDetails() {
      if (!this.trainingRecommendationRef) return;

      try {
        const recoId = this.trainingRecommendationRef.split("/")[1];
        const response = await fetch(`/fhir/Basic/${recoId}`);
        if (!response.ok) return;

        const reco = await response.json();
        const getExt = (url, type) => {
          const ext = reco.extension?.find((e) => e.url.includes(url));
          return ext ? ext[type] : null;
        };

        this.trainingRecommendationDetails = {
          id: recoId,
          title: getExt("ihris-basic-name", "valueString"),
          description: getExt("description", "valueString"),
          institution: getExt("planning-institution", "valueString"),
          typeDisplay: getExt("training-type", "valueCoding")?.display,
          qualificationLevel: getExt("qualification-level", "valueCoding")
            ?.display,
          country: getExt("country", "valueCoding")?.display,
          location: getExt("training-location", "valueString"),
          methodology: getExt("learning-methodology", "valueCoding")?.display,
          startDate: getExt("start-date", "valueDate"),
          endDate: getExt("end-date", "valueDate"),
          fiscalYear: getExt("fiscal-year", "valueString"),
          totalParticipants: getExt("total-participants", "valueInteger"),
        };
      } catch (error) {
        console.error("Error loading training recommendation details:", error);
      }
    },

    async loadLeaveRequests() {
      if (!this.leaveRequestRefs || this.leaveRequestRefs.length === 0) return;

      try {
        const requests = await Promise.all(
          this.leaveRequestRefs.map(async (ref) => {
            try {
              const id = ref.split("/")[1];
              const response = await fetch(`/fhir/Basic/${id}`);
              if (!response.ok) return null;

              const resource = await response.json();
              const getExt = (url, type) => {
                const ext = resource.extension?.find((e) =>
                  e.url.includes(url),
                );
                return ext ? ext[type] : null;
              };

              const statusCoding = getExt("status", "valueCoding");
              const docs = resource.extension?.filter((e) =>
                e.url.includes("supporting-document"),
              );

              return {
                id,
                status: statusCoding?.code || "",
                statusDisplay: statusCoding?.display || "",
                startDate: getExt("start-date", "valueDate"),
                endDate: getExt("end-date", "valueDate"),
                returnDate: getExt("return-date", "valueDate"),
                requestDate: getExt("request-date", "valueDate"),
                cancelDate: getExt("cancel-date", "valueDate"),
                days: getExt("days", "valueInteger") || 0,
                comments: getExt("comments", "valueString") || "",
                supportingDocuments: docs?.map((d) => d.valueAttachment) || [],
              };
            } catch (error) {
              console.error("Error loading leave request:", error);
              return null;
            }
          }),
        );

        this.leaveRequests = requests
          .filter(Boolean)
          .sort((a, b) => (a.startDate < b.startDate ? 1 : -1));
      } catch (error) {
        console.error("Error loading leave requests:", error);
      }
    },

    // ── Display helpers ─────────────────────────────────────────────────
    getTrainingTypeColor() {
      const colorMap = {
        parttime: "blue",
        shortterm: "orange",
        longterm: "purple",
      };
      return colorMap[this.studyLeaveData?.trainingType] || "green";
    },

    getPlanStatusColor(status) {
      const colorMap = {
        draft: "grey",
        undersupervisorreview: "orange",
        approved: "success",
        rejected: "error",
      };
      return colorMap[status] || "grey";
    },

    getStatusColor(status) {
      const statusMap = {
        draft: "grey",
        undersupervisorreview: "orange",
        underhodreview: "deep-purple",
        underhrreview: "blue",
        approved: "success",
        rejected: "error",
        cancelled: "error",
      };
      return statusMap[status] || "grey";
    },

    getStatusIcon(status) {
      const iconMap = {
        draft: "mdi-file-document-edit",
        undersupervisorreview: "mdi-account-tie",
        underhodreview: "mdi-account-star",
        underhrreview: "mdi-account-group",
        approved: "mdi-check-circle",
        rejected: "mdi-close-circle",
      };
      return iconMap[status] || "mdi-help-circle";
    },

    outcomeLabel(outcome) {
      if (!outcome) return "Not Recorded";
      const item = this.outcomeValueSetItems.find((i) => i.code === outcome);
      return item ? item.display || item.code : outcome;
    },

    outcomeKey(outcome) {
      const map = { completed: "done", failed: "error", ongoing: "warn" };
      return map[outcome] || "none";
    },

    formatDate(dateString) {
      if (!dateString) return "N/A";
      const date = new Date(dateString);
      return date.toLocaleDateString("en-US", {
        year: "numeric",
        month: "short",
        day: "numeric",
      });
    },

    downloadDocument(doc) {
      if (doc.data && doc.contentType) {
        const blob = this.base64toBlob(doc.data, doc.contentType);
        const url = window.URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.download = doc.title || "document";
        link.click();
        window.URL.revokeObjectURL(url);
      }
    },

    base64toBlob(base64Data, contentType) {
      contentType = contentType || "";
      const sliceSize = 1024;
      const byteCharacters = atob(base64Data);
      const bytesLength = byteCharacters.length;
      const slicesCount = Math.ceil(bytesLength / sliceSize);
      const byteArrays = new Array(slicesCount);

      for (let sliceIndex = 0; sliceIndex < slicesCount; ++sliceIndex) {
        const begin = sliceIndex * sliceSize;
        const end = Math.min(begin + sliceSize, bytesLength);

        const bytes = new Array(end - begin);
        for (let offset = begin, i = 0; offset < end; ++i, ++offset) {
          bytes[i] = byteCharacters[offset].charCodeAt(0);
        }
        byteArrays[sliceIndex] = new Uint8Array(bytes);
      }

      return new Blob(byteArrays, { type: contentType });
    },

    // ── Navigation ───────────────────────────────────────────────────────
    viewLeaveRequest(id) {
      this.$router.push({
        path: "/custom/leave-request-view",
        query: {
          path: "/lesotho/components/leave",
          leave: id,
        },
      });
    },

    goBack() {
      if (this.queries && this.queries.returnPath) {
        this.$router.push({
          path: this.queries.returnPath,
          query: this.queries.returnQuery
            ? JSON.parse(this.queries.returnQuery)
            : undefined,
        });
      } else if (window.history.length > 1) {
        this.$router.go(-1);
      } else {
        this.$router.push("/");
      }
    },

    scrollTo(section) {
      const el = document.getElementById(`section-${section}`);
      if (el) el.scrollIntoView({ behavior: "smooth" });
    },
  },
};
</script>

